/****************************************************************************
 * Name: camera_bench_conversion
 *
 * Description:
 *   A/B benchmark to separate PSRAM access bottleneck from XIP flash
 *   instruction-fetch bottleneck in uyvy_to_rgb565_scaled().
 *
 *   Path A — "psram": convert directly from PSRAM source (scattered reads).
 *   Path B — "sram" : memcpy a 160x160 UYVY crop to SRAM first, then
 *            convert from there (sequential source reads).
 *
 *   Both paths output to the same destination buffer.  memcpy is timed
 *   separately and reported independently.
 *
 *   Each path runs BENCH_ROUNDS iterations; elapsed time is accumulated
 *   to overcome the 10 ms tick resolution.
 *
 ****************************************************************************/

#define BENCH_ROUNDS     10
#define BENCH_CROP_W     160
#define BENCH_CROP_H     160
#define BENCH_CROP_SIZE  (BENCH_CROP_W * BENCH_CROP_H * 2)  /* 51200 */

static void camera_bench_conversion(void)
{
  /* Ensure a frame exists in PSRAM */

  if (!g_framebuf_allocated)
    {
      printf("[bench] FAIL: no PSRAM framebuf — run camera buf first\n");
      return;
    }

  /* Single-frame DMA capture so source data is real, not stale */

  printf("[bench] capturing one frame to PSRAM ...\n");

  int ret = dvp_single_frame_capture();
  if (ret < 0)
    {
      printf("[bench] FAIL: capture error %d\n", ret);
      return;
    }

  /* Allocate SRAM staging buffer for the cropped source region */

  static uint8_t sram_stage[BENCH_CROP_SIZE];
  const uint8_t *psram_src = (const uint8_t *)g_camera_buf[0];
  uint8_t *dst = (uint8_t *)PREVIEW_ADDR;  /* PSRAM output, shared */

  clock_t t0;
  uint32_t elapsed_a;
  uint32_t elapsed_b;
  uint32_t elapsed_memcpy;
  uint32_t elapsed_cvt_sram;
  int i;

  /* ---- Path A: convert directly from PSRAM ---- */

  t0 = clock_systime_ticks();

  for (i = 0; i < BENCH_ROUNDS; i++)
    {
      uyvy_to_rgb565_scaled(psram_src, dst,
                            CAMERA_HRES, CAMERA_VRES,
                            BENCH_CROP_W, BENCH_CROP_H);
    }

  elapsed_a = (uint32_t)TICK2MSEC(clock_systime_ticks() - t0);

  /* ---- memcpy: PSRAM -> SRAM (timed separately) ---- */

  t0 = clock_systime_ticks();

  for (i = 0; i < BENCH_ROUNDS; i++)
    {
      memcpy(sram_stage, psram_src, BENCH_CROP_SIZE);
    }

  elapsed_memcpy = (uint32_t)TICK2MSEC(clock_systime_ticks() - t0);

  /* ---- Path B: convert from SRAM ---- */

  t0 = clock_systime_ticks();

  for (i = 0; i < BENCH_ROUNDS; i++)
    {
      uyvy_to_rgb565_scaled(sram_stage, dst,
                            BENCH_CROP_W, BENCH_CROP_H,
                            BENCH_CROP_W, BENCH_CROP_H);
    }

  elapsed_cvt_sram = (uint32_t)TICK2MSEC(clock_systime_ticks() - t0);

  /* ---- Report ---- */

  elapsed_b = elapsed_memcpy + elapsed_cvt_sram;

  /* Avoid division by zero */

  if (elapsed_a == 0) elapsed_a = 1;
  if (elapsed_memcpy == 0) elapsed_memcpy = 1;
  if (elapsed_cvt_sram == 0) elapsed_cvt_sram = 1;
  if (elapsed_b == 0) elapsed_b = 1;

  printf("[bench] src=%dx%d UYVY dst=%dx%d RGB565  rounds=%d\n",
         CAMERA_HRES, CAMERA_VRES, BENCH_CROP_W, BENCH_CROP_H,
         BENCH_ROUNDS);
  printf("[bench] PSRAM convert : %lu ms total, %lu ms/iter\n",
         (unsigned long)elapsed_a,
         (unsigned long)(elapsed_a / BENCH_ROUNDS));
  printf("[bench] memcpy PSRAM>S: %lu ms total, %lu ms/iter\n",
         (unsigned long)elapsed_memcpy,
         (unsigned long)(elapsed_memcpy / BENCH_ROUNDS));
  printf("[bench] SRAM  convert : %lu ms total, %lu ms/iter\n",
         (unsigned long)elapsed_cvt_sram,
         (unsigned long)(elapsed_cvt_sram / BENCH_ROUNDS));
  printf("[bench] B total (mcp+cvt): %lu ms total, %lu ms/iter\n",
         (unsigned long)elapsed_b,
         (unsigned long)(elapsed_b / BENCH_ROUNDS));
}

